def compute(vars):
    cost_millions = vars["v1"]
    shares_millions = vars["v2"]
    if shares_millions == 0:
        return None
    cost_per_share = cost_millions / shares_millions
    return {
        "value": cost_per_share,
        "trace": {
            "cost_millions": cost_millions,
            "shares_millions": shares_millions,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "USD/share"
            }
        }
    }
